type MemoryCard = { id: string; pairId: string; icon: string };
type GameStatus = 'idle' | 'playing' | 'won' | 'lost';
const memoryPairs = ['🐱','🐶','🐰','🐹','🦊','🐼'];
const shuffleCards = <T,>(items: T[]) => items.map((value) => ({ value, sort: Math.random() })).sort((a,b) => a.sort-b.sort).map(({ value }) => value);

function MiniGame({ game, setGame, reward, reducedMotion }: { game: string; setGame: (g: string) => void; reward: (result: ReturnType<typeof createMiniGameReward>) => void; reducedMotion: boolean }) {
  const meta = miniGameCatalog.find((item) => item[0] === game) as MiniGameMeta | undefined;
  const [status, setStatus] = useState<GameStatus>('idle');
  const [countdown, setCountdown] = useState(3);
  const [time, setTime] = useState(30);
  const [score, setScore] = useState(0);
  const [paused, setPaused] = useState(false);
  const rewarded = useRef(false);

  useEffect(() => {
    setStatus('idle'); setCountdown(3); setTime(game === 'memory-match' ? 45 : 30); setScore(0); setPaused(false); rewarded.current = false;
  }, [game]);
  useEffect(() => { if (status !== 'idle') return undefined; const id = window.setInterval(() => setCountdown((c) => { if (c <= 1) { setStatus('playing'); return 0; } return c - 1; }), 700); return () => window.clearInterval(id); }, [status]);
  useEffect(() => { if (status !== 'playing' || paused || game === 'memory-match') return undefined; const id = window.setInterval(() => setTime((t) => Math.max(0, t - 1)), 1000); return () => window.clearInterval(id); }, [game, paused, status]);
  useEffect(() => { if (time === 0 && status === 'playing') setStatus(score > 0 ? 'won' : 'lost'); }, [score, status, time]);
  useEffect(() => { if ((status === 'won' || status === 'lost') && !rewarded.current) { rewarded.current = true; const difficulty = meta?.[6] ?? 'Easy'; reward(createMiniGameReward({ difficulty, reason: meta?.[2] ?? 'Mini Game', actionId: game, score, multiplier: 1 })); } }, [game, meta, reward, score, status]);
  if (!meta) return <PixelCard><p className="text-[10px]">Game not found.</p><PixelButton onClick={() => setGame('none')} tone="mt-3 bg-white">Exit</PixelButton></PixelCard>;
  const controls = <div className="mb-3 flex flex-wrap gap-2"><PixelButton onClick={() => setPaused((p) => !p)} tone="bg-white">{paused ? 'Resume' : 'Pause'}</PixelButton><PixelButton onClick={() => setGame('none')} tone="bg-white">Exit</PixelButton><span className="border-2 border-slate-950 bg-white px-3 py-2 text-[10px]">Score {score}</span><span className="border-2 border-slate-950 bg-white px-3 py-2 text-[10px]">Time {time}s</span></div>;
  if (status === 'idle') return <PixelCard className="text-center"><h2 className="text-sm">{meta[1]} {meta[2]}</h2><p className="my-4 text-5xl">{countdown}</p><p className="text-[10px]">Get ready...</p><PixelButton onClick={() => setGame('none')} tone="mt-4 bg-white">Exit</PixelButton></PixelCard>;
  if (status === 'won' || status === 'lost') return <PixelCard className="text-center"><h2 className="text-sm">{status === 'won' ? 'Result: Great job!' : 'Result: Try again!'}</h2><p className="my-3 text-[10px]">{meta[2]} score: {score}. Reward is granted once per run.</p><div className="mx-auto max-w-xs"><PixelButton onClick={() => { rewarded.current = false; setStatus('idle'); setCountdown(3); setTime(game === 'memory-match' ? 45 : 30); setScore(0); }} tone="bg-yellow-200">Restart</PixelButton><PixelButton onClick={() => setGame('none')} tone="mt-2 bg-white">Back to Hub</PixelButton></div></PixelCard>;
  if (paused) return <PixelCard>{controls}<div className="grid h-48 place-items-center border-4 border-slate-950 bg-white text-center text-[10px]">Paused. Resume or exit anytime.</div></PixelCard>;
  if (game === 'memory-match') return <MemoryMatchGame controls={controls} onScore={setScore} onWin={(moves) => { setScore(Math.max(12, 60 - moves * 2)); setStatus('won'); }} />;
  return <GenericMiniGame game={game} title={meta[2]} icon={meta[1]} score={score} setScore={setScore} setStatus={setStatus} controls={controls} reducedMotion={reducedMotion} />;
}

function MemoryMatchGame({ controls, onScore, onWin }: { controls: React.ReactNode; onScore: (score: number) => void; onWin: (moves: number) => void }) {
  const buildCards = useCallback((): MemoryCard[] => shuffleCards(memoryPairs.flatMap((icon, pairIndex) => ([{ id:`${pairIndex}-a-${crypto.randomUUID()}`, pairId:`pair-${pairIndex}`, icon }, { id:`${pairIndex}-b-${crypto.randomUUID()}`, pairId:`pair-${pairIndex}`, icon }]))), []);
  const [cards, setCards] = useState<MemoryCard[]>(buildCards);
  const [flippedIds, setFlippedIds] = useState<string[]>([]);
  const [matchedPairIds, setMatchedPairIds] = useState<string[]>([]);
  const [moves, setMoves] = useState(0);
  const [lockBoard, setLockBoard] = useState(false);
  const timeoutRef = useRef<number | null>(null);
  useEffect(() => () => { if (timeoutRef.current) window.clearTimeout(timeoutRef.current); }, []);
  useEffect(() => { onScore(matchedPairIds.length * 10); if (matchedPairIds.length === memoryPairs.length) onWin(moves); }, [matchedPairIds.length, moves, onScore, onWin]);
  const clickCard = (card: MemoryCard) => {
    if (lockBoard || flippedIds.includes(card.id) || matchedPairIds.includes(card.pairId)) return;
    const next = [...flippedIds, card.id];
    setFlippedIds(next);
    if (next.length !== 2) return;
    setLockBoard(true); setMoves((m) => m + 1);
    const [a,b] = next.map((id) => cards.find((c) => c.id === id));
    if (a && b && a.pairId === b.pairId) { setMatchedPairIds((ids) => Array.from(new Set([...ids, a.pairId]))); setFlippedIds([]); setLockBoard(false); return; }
    timeoutRef.current = window.setTimeout(() => { setFlippedIds([]); setLockBoard(false); }, 700);
  };
  return <PixelCard>{controls}<h2 className="mb-2 text-sm">Memory Match · Moves {moves}</h2><div className="grid grid-cols-3 gap-2 sm:max-w-lg sm:grid-cols-4">{cards.map((card) => { const shown = flippedIds.includes(card.id) || matchedPairIds.includes(card.pairId); return <button type="button" key={card.id} disabled={lockBoard || matchedPairIds.includes(card.pairId)} onClick={() => clickCard(card)} className={`h-16 border-4 border-slate-950 text-2xl sm:h-20 ${shown ? 'bg-yellow-100' : 'bg-white'}`}>{shown ? card.icon : '?'}</button>; })}</div><PixelButton onClick={() => { if (timeoutRef.current) window.clearTimeout(timeoutRef.current); setCards(buildCards()); setFlippedIds([]); setMatchedPairIds([]); setMoves(0); setLockBoard(false); }} tone="mt-4 bg-white">Restart Board</PixelButton></PixelCard>;
}

function GenericMiniGame({ game, title, icon, score, setScore, setStatus, controls, reducedMotion }: { game: string; title: string; icon: string; score: number; setScore: (fn: (s: number) => number) => void; setStatus: (s: GameStatus) => void; controls: React.ReactNode; reducedMotion: boolean }) {
  const [target, setTarget] = useState({ left: 42, top: 45, icon });
  const good = ['catch-food','bubble-pop','whack-a-bug','coin-rain','fishing-pond','star-catcher','cleaning-rush'].includes(game);
  const tap = () => { setScore((s) => Math.max(0, s + (good ? 1 : 2))); setTarget({ left: Math.random() * 78, top: Math.random() * 68, icon: ['🍎','🫧','🪲','🪙','🎣','⭐','🧼','🏃','➰','🍪','🏎️','🔁','🍓','🧩','⚡'][Math.floor(Math.random()*15)] ?? icon }); if (score >= 9) setStatus('won'); };
  const buttons = game === 'simon-says' || game === 'tap-rhythm' || game === 'fruit-sort' ? ['◀','●','▶','■'] : game === 'maze-walk' ? ['↑','←','→','↓'] : ['TAP'];
  return <PixelCard>{controls}<h2 className="mb-3 text-sm">{icon} {title}</h2><div className="relative h-64 overflow-hidden border-4 border-slate-950 bg-sky-100 sm:h-80"><button type="button" onClick={tap} className={`absolute border-4 border-slate-950 bg-white p-3 text-3xl ${reducedMotion ? '' : 'animate-bounce'}`} style={{ left:`${target.left}%`, top:`${target.top}%` }}>{target.icon}</button><div className="absolute bottom-2 left-2 right-2 grid grid-cols-2 gap-2 sm:grid-cols-4">{buttons.map((b) => <button key={b} type="button" onClick={tap} className="border-4 border-slate-950 bg-yellow-100 p-3 text-xl">{b}</button>)}</div></div></PixelCard>;
}
